{"code_block": "codes = ["9783541813919","9789466697461","9783980361396","9784476566804","9782795866647","9785950736933","9789766476526","9785911781255","9787284659245","9784148251559"]
# verify lengths
assert all(len(c)==13 for c in codes)

def is_valid(digs, w):
    total = sum(int(digs[i]) * (1 if i%2==0 else w) for i in range(13))
    return total % 10 == 0

def swap(d, y):
    lst = list(d)
    lst[y], lst[y+1] = lst[y+1], lst[y]
    return ''.join(lst)

candidates = []
for w in [2,4,5,6,7,8,9,3]: # include 3 as well
    for y in range(3,11):
        ok=True
        for code in codes:
            sc=swap(code,y)
            if not is_valid(sc,w):
                ok=False
                break
        if ok:
            candidates.append((w,y))
